## 6️⃣ 測試

### 6.1 單元測試（Jest + Testing Library）

```bash
npm i -D jest @testing-library/react @testing-library/jest-dom @testing-library/user-event
```

```tsx
// src/components/__tests__/ProductCard.test.tsx
import { render, screen, fireEvent } from '@testing-library/react';
import ProductCard from '../ProductCard';
import { BrowserRouter } from 'react-router-dom';
import { useStore } from '../../store/useStore';

jest.mock('../../store/useStore');

describe('ProductCard', () => {
  const mockAddToCart = jest.fn();
  beforeEach(() => {
    (useStore as jest.Mock).mockReturnValue({ addToCart: mockAddToCart });
  });

  it('renders product info', () => {
    render(
      <BrowserRouter>
        <ProductCard product={{ id: '1', name: 'Test', price: 99, image: '/test.jpg' }} />
      </BrowserRouter>
    );

    expect(screen.getByText('Test')).toBeInTheDocument();
    expect(screen.getByText('$99')).toBeInTheDocument();
  });

  it('calls addToCart when button clicked', () => {
    render(
      <BrowserRouter>
        <ProductCard product={{ id: '1', name: 'Test', price: 99, image: '/test.jpg' }} />
      </BrowserRouter>
    );

    fireEvent.click(screen.getByRole('button', { name: /加入購物車/i }));
    expect(mockAddToCart).toHaveBeenCalledWith({ id: '1', name: 'Test', price: 99, image: '/test.jpg', quantity: 1 });
  });
});
```

### 6.2 端到端測試（Cypress）

```bash
npm i -D cypress
npx cypress open
```

```js
// cypress/e2e/cart.cy.js
describe('購物車流程', () => {
  it('能夠將商品加入購物車並結帳', () => {
    cy.visit('/');
    cy.contains('Test Product').click();
    cy.contains('加入購物車').click();
    cy.visit('/cart');
    cy.contains('Test Product').should('be.visible');
    cy.contains('前往結帳').click();
    cy.url().should('include', '/checkout');
  });
